#endif
layout(std140) uniform v_buffer0 {
	vec4 v_cb0[20];
} _v_buffer0;
layout(std140) uniform v_buffer1 {
	vec4 v_cb1;
} _v_buffer1;
layout(std140) uniform v_buffer2 {
	vec4 v_cb2[4];
} _v_buffer2;
layout(std140) uniform v_buffer3 {
	vec4 v_cb3[5];
} _v_buffer3;
in highp vec4 in_POSITION0;
in highp vec2 in_TEXCOORD0;
in highp vec2 in_TEXCOORD1;
out highp vec2 vs_TEXCOORD0;
out highp vec2 vs_TEXCOORD1;
out highp vec2 vs_TEXCOORD2;
out highp vec2 vs_TEXCOORD4;
out highp vec4 vs_TEXCOORD3;
out highp vec2 vs_TEXCOORD5;
out highp vec4 vs_COLOR0;
vec4 u_xlat0;
vec2 u_xlat1;
vec2 u_xlat2;
vec3 u_xlat3;
vec3 u_xlat4;
vec2 u_xlat10;
vec2 u_xlat11;
float u_xlat15;
void main()
{
    u_xlat0 = in_POSITION0.yyyy * _v_buffer2.v_cb2[1];
    u_xlat0 = _v_buffer2.v_cb2[0] * in_POSITION0.xxxx + u_xlat0;
    u_xlat0 = _v_buffer2.v_cb2[2] * in_POSITION0.zzzz + u_xlat0;
    gl_Position = _v_buffer2.v_cb2[3] * in_POSITION0.wwww + u_xlat0;
    vs_TEXCOORD1.xy = in_TEXCOORD1.xy * _v_buffer0.v_cb0[19].xy + _v_buffer0.v_cb0[19].zw;
    u_xlat0.xy = in_TEXCOORD0.xy * _v_buffer0.v_cb0[19].xy + _v_buffer0.v_cb0[19].zw;
    vs_TEXCOORD0.xy = u_xlat0.xy;
    u_xlat10.xy = _v_buffer0.v_cb0[6].zw + vec2(0.5, 0.5);
    u_xlat10.xy = (-u_xlat10.xy) + u_xlat0.xy;
    u_xlat1.x = u_xlat10.x * _v_buffer0.v_cb0[4].w;
    u_xlat1.y = u_xlat10.y * _v_buffer0.v_cb0[5].x;
    u_xlat10.x = _v_buffer0.v_cb0[17].w + _v_buffer1.v_cb1.x;
    u_xlat15 = u_xlat10.x * _v_buffer0.v_cb0[6].y;
    u_xlat2.x = sin(u_xlat15);
    u_xlat3.x = cos(u_xlat15);
    u_xlat4.z = u_xlat2.x;
    u_xlat4.y = u_xlat3.x;
    u_xlat4.x = (-u_xlat2.x);
    u_xlat2.y = dot(u_xlat1.xy, u_xlat4.xy);
    u_xlat2.x = dot(u_xlat1.xy, u_xlat4.yz);
    vs_TEXCOORD2.xy = u_xlat2.xy + vec2(0.5, 0.5);
    u_xlat1.x = _v_buffer0.v_cb0[10].w + 0.5;
    u_xlat1.y = _v_buffer0.v_cb0[11].x + 0.5;
    u_xlat1.xy = u_xlat0.xy + (-u_xlat1.xy);
    u_xlat1.xy = u_xlat1.xy * _v_buffer0.v_cb0[9].xy;
    u_xlat15 = u_xlat10.x * _v_buffer0.v_cb0[10].z;
    u_xlat2.x = sin(u_xlat15);
    u_xlat3.x = cos(u_xlat15);
    u_xlat4.z = u_xlat2.x;
    u_xlat4.y = u_xlat3.x;
    u_xlat4.x = (-u_xlat2.x);
    u_xlat11.y = dot(u_xlat1.xy, u_xlat4.xy);
    u_xlat11.x = dot(u_xlat1.xy, u_xlat4.yz);
    vs_TEXCOORD4.xy = u_xlat11.xy + vec2(0.5, 0.5);
    u_xlat15 = u_xlat10.x * _v_buffer0.v_cb0[5].z;
    u_xlat15 = sin(u_xlat15);
    u_xlat15 = u_xlat15 + _v_buffer0.v_cb0[6].x;
    u_xlat15 = u_xlat15 * _v_buffer0.v_cb0[5].w;
#ifdef UNITY_ADRENO_ES3
    u_xlat15 = min(max(u_xlat15, 0.0), 1.0);
#else
    u_xlat15 = clamp(u_xlat15, 0.0, 1.0);
#endif
    u_xlat15 = u_xlat15 + -1.0;
    vs_TEXCOORD3.x = _v_buffer0.v_cb0[5].y * u_xlat15 + 1.0;
    u_xlat15 = u_xlat10.x * _v_buffer0.v_cb0[9].w;
    u_xlat1.xy = u_xlat10.xx * _v_buffer0.v_cb0[15].wx;
    u_xlat10.x = sin(u_xlat15);
    u_xlat10.x = u_xlat10.x + (-_v_buffer0.v_cb0[10].y);
    u_xlat10.x = u_xlat10.x * _v_buffer0.v_cb0[10].x;
#ifdef UNITY_ADRENO_ES3
    u_xlat10.x = min(max(u_xlat10.x, 0.0), 1.0);
#else
    u_xlat10.x = clamp(u_xlat10.x, 0.0, 1.0);
#endif
    u_xlat10.x = u_xlat10.x + -1.0;
    vs_TEXCOORD3.y = _v_buffer0.v_cb0[9].z * u_xlat10.x + 1.0;
    u_xlat10.x = sin(u_xlat1.y);
    u_xlat2.x = cos(u_xlat1.x);
    u_xlat1.x = sin(u_xlat1.x);
    u_xlat10.x = u_xlat10.x + (-_v_buffer0.v_cb0[15].z);
    u_xlat10.x = u_xlat10.x * _v_buffer0.v_cb0[15].y;
#ifdef UNITY_ADRENO_ES3
    u_xlat10.x = min(max(u_xlat10.x, 0.0), 1.0);
#else
    u_xlat10.x = clamp(u_xlat10.x, 0.0, 1.0);
#endif
    u_xlat10.x = u_xlat10.x + -1.0;
    vs_TEXCOORD3.z = _v_buffer0.v_cb0[14].w * u_xlat10.x + 1.0;
    u_xlat10.xy = _v_buffer0.v_cb0[16].xy + vec2(0.5, 0.5);
    u_xlat0.xy = (-u_xlat10.xy) + u_xlat0.xy;
    u_xlat0.xy = u_xlat0.xy * _v_buffer0.v_cb0[14].yz;
    u_xlat3.z = u_xlat1.x;
    u_xlat3.y = u_xlat2.x;
    u_xlat3.x = (-u_xlat1.x);
    u_xlat1.y = dot(u_xlat0.xy, u_xlat3.xy);
    u_xlat1.x = dot(u_xlat0.xy, u_xlat3.yz);
    vs_TEXCOORD5.xy = u_xlat1.xy + vec2(0.5, 0.5);
    u_xlat0 = _v_buffer3.v_cb3[4] * vec4(2.0, 2.0, 2.0, 2.0) + _v_buffer0.v_cb0[1];
    u_xlat0 = u_xlat0 + vec4(-1.0, -1.0, -1.0, -1.0);
    vs_COLOR0 = _v_buffer0.v_cb0[18].xxxx * u_xlat0 + vec4(1.0, 1.0, 1.0, 1.0);
